-- Product center scene settings. Existing administrator changes are preserved.
SET NAMES utf8mb4;
START TRANSACTION;
INSERT INTO site_settings (id, configuration) SELECT 'product-showcase',CONVERT( USING utf8mb4) WHERE NOT EXISTS (SELECT 1 FROM site_settings WHERE id='product-showcase');
INSERT INTO app_migrations (id) SELECT '2026-10-17-product-showcase-v1' WHERE NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-17-product-showcase-v1');
COMMIT;
